import {fromCircumference,fromPhoto} from './measurement.js';
const app=document.querySelector('#app');
let lang=new URLSearchParams(location.search).get('lang')==='fr'?'fr':'en';
let screen='qr',history=[],result=null,photo=null,points=[],phase='reference',referenceMm=85.6,stream=null;
const mobile=/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)||new URLSearchParams(location.search).has('mobile');
const translations={
en:{title:"Let's find your perfect size",subtitle:'Find your perfect size for this ring with our Virtual Sizer',scan:'Scan the QR and follow the steps, it takes less than 2 minutes.',legal:'Your photos stay on your device. Read our',privacy:'privacy policy',terms:'measurement guide',and:'and',device:'Continue on this device',welcome:'Find your perfect ring size',intro:'A few simple steps to find a ring that fits you comfortably.',minutes:'Takes less than 2 minutes',private:'Private. Your photos stay on this device.',need:'An existing ring or a strip of paper',start:'Find my size',choose:'How would you like to measure?',chooseSub:'Choose the method that works best for you.',ring:'Measure an existing ring',ringSub:'Take a photo with a reference object.',finger:'Measure your finger',fingerSub:'Use a strip of paper or a flexible tape.',back:'Back',step:'Step',prepare:'Get your ring ready',prepareSub:'Use a ring that fits the finger you plan to wear it on.',photo1:'Place the ring flat on a plain, light surface.',photo2:'Put a standard card or ruler next to it, on the same surface.',photo3:'Take the photo directly from above. Keep the full ring and reference in focus.',photo4:'Use a blank card or cover any personal information.',upload:'Choose a photo',camera:'Use camera',photoNote:'Only the ring’s inner diameter is measured. No image is uploaded.',wrap:'Measure your finger',wrapSub:'A paper strip gives you the circumference of your finger.',wrap1:'Cut a narrow strip of paper and wrap it around the base of your finger.',wrap2:'Keep it snug and comfortable. Make sure it can slide over the knuckle.',wrap3:'Mark where the two ends meet, then lay the strip flat.',wrap4:'Measure the distance to the mark in millimetres. Repeat twice to check.',input:'Enter circumference',circLabel:'Finger circumference',circSub:'Enter the length you measured, in millimetres.',size:'See my size',range:'Enter a number between 40 and 80 mm.',ref:'Calibrate your photo',refSub:'Tap both ends of the reference object in your photo.',object:'Reference object',card:'Standard card — long edge (85.60 mm)',shortCard:'Standard card — short edge (53.98 mm)',ruler:'Ruler — choose your measured distance',custom:'Reference length',reset:'Reset points',next:'Continue',refHelp:'Tap the two corners of the same card edge. Use a blank card or ruler only.',diam:'Measure the inside of the ring',diamSub:'Tap the two opposite inner edges of the ring, through its centre.',diamHelp:'Measure the empty space inside the ring, not the metal. Keep the diameter on the same plane as the reference.',points:'points selected',retake:'Choose another photo',done:'Your estimated ring size',doneSub:'Based on your measurement, this is your closest standard size.',us:'US size',eu:'EU size',circ:'Circumference',diameter:'Inner diameter',resultNote:'This is a standard size estimate, not a Circular-specific recommendation. Check the ring maker’s chart and confirm with a physical sizing kit before ordering.',repeat:'Measure again',save:'Save my result',saved:'Result saved on this device.',chart:'View size chart',out:'This measurement is outside the usual size range. Check your calibration and ring edges.',method:'Method',photoMethod:'Calibrated ring photo',paperMethod:'Finger circumference',policyTitle:'Privacy policy',policyText:'This standalone sizer processes photos locally in your browser. Photos are never sent to a server. Camera access is requested only when you choose “Use camera”. The camera stops when you leave the capture screen. Saved results stay in your browser’s local storage and can be cleared using your browser settings. The QR code contains only this page’s URL, not your photos or measurements.',guideTitle:'Measurement guide',guideText:'Use this tool as an estimate. Photo measurements require a known reference length placed on the same flat surface as the ring. Take the photo straight down to minimise perspective distortion, then select the reference and inner ring edges carefully. Finger circumference must be measured with a snug paper strip or flexible tape. Ring fit varies with finger shape, temperature, time of day, ring width, and the manufacturer’s sizing system. Confirm your size with a physical kit before purchasing.',cameraError:'Camera is unavailable or permission was declined. You can choose a photo instead.',capture:'Take photo',cancel:'Cancel',cameraTitle:'Take your ring photo',cameraSub:'Keep the ring and reference flat, visible and in focus.',loading:'Opening camera…',imageError:'This file could not be read. Please choose a JPG, PNG or WebP photo.',localQr:'To scan this QR on a phone, open the published site. Localhost only opens on this computer.',close:'Close',chartTitle:'Standard ring size chart',chartSub:'Approximate US sizes and inner dimensions.'},
fr:{title:'Trouvons votre taille idéale',subtitle:'Trouvez la taille parfaite de votre bague avec notre outil de mesure',scan:'Scannez le QR code et suivez les étapes, cela prend moins de 2 minutes.',legal:'Vos photos restent sur votre appareil. Consultez notre',privacy:'politique de confidentialité',terms:'guide de mesure',and:'et notre',device:'Continuer sur cet appareil',welcome:'Trouvez votre taille de bague',intro:'Quelques étapes simples pour trouver une bague confortable.',minutes:'Moins de 2 minutes',private:'Vos photos restent sur cet appareil.',need:'Une bague ou une bande de papier',start:'Trouver ma taille',choose:'Comment souhaitez-vous mesurer ?',chooseSub:'Choisissez la méthode qui vous convient.',ring:'Mesurer une bague',ringSub:'Prenez une photo avec un objet de référence.',finger:'Mesurer votre doigt',fingerSub:'Utilisez une bande de papier ou un mètre souple.',back:'Retour',step:'Étape',prepare:'Préparez votre bague',prepareSub:'Utilisez une bague adaptée au doigt que vous souhaitez mesurer.',photo1:'Posez la bague à plat sur une surface claire et unie.',photo2:'Placez une carte standard ou une règle à côté, sur le même plan.',photo3:'Prenez la photo du dessus. La bague et la référence doivent être nettes.',photo4:'Utilisez une carte vierge ou masquez les informations personnelles.',upload:'Choisir une photo',camera:'Utiliser la caméra',photoNote:'Seul le diamètre intérieur est mesuré. Aucune photo n’est envoyée.',wrap:'Mesurez votre doigt',wrapSub:'Une bande de papier permet de mesurer la circonférence.',wrap1:'Enroulez une bande étroite de papier autour de la base du doigt.',wrap2:'Ajustez-la confortablement et vérifiez qu’elle passe l’articulation.',wrap3:'Marquez le point de rencontre des deux extrémités, puis posez le papier à plat.',wrap4:'Mesurez la distance en millimètres. Répétez deux fois pour vérifier.',input:'Saisir la circonférence',circLabel:'Circonférence du doigt',circSub:'Saisissez la longueur mesurée en millimètres.',size:'Voir ma taille',range:'Saisissez une valeur entre 40 et 80 mm.',ref:'Calibrez votre photo',refSub:'Touchez les deux extrémités de l’objet de référence.',object:'Objet de référence',card:'Carte standard — longueur (85,60 mm)',shortCard:'Carte standard — largeur (53,98 mm)',ruler:'Règle — distance connue',custom:'Longueur de référence',reset:'Effacer les points',next:'Continuer',refHelp:'Touchez les deux coins du même bord. Utilisez une carte vierge ou une règle.',diam:'Mesurez l’intérieur de la bague',diamSub:'Touchez deux bords intérieurs opposés, en passant par le centre.',diamHelp:'Mesurez l’espace intérieur, pas le métal. La référence doit être sur le même plan.',points:'points sélectionnés',retake:'Choisir une autre photo',done:'Votre taille de bague estimée',doneSub:'Voici la taille standard la plus proche de votre mesure.',us:'Taille US',eu:'Taille EU',circ:'Circonférence',diameter:'Diamètre intérieur',resultNote:'Estimation standard, pas une recommandation spécifique Circular. Consultez le tableau du fabricant et confirmez avec un kit de tailles avant de commander.',repeat:'Mesurer à nouveau',save:'Enregistrer mon résultat',saved:'Résultat enregistré sur cet appareil.',chart:'Voir le tableau des tailles',out:'Cette mesure dépasse la plage habituelle. Vérifiez la calibration et les bords de la bague.',method:'Méthode',photoMethod:'Photo de bague calibrée',paperMethod:'Circonférence du doigt',policyTitle:'Politique de confidentialité',policyText:'Cet outil traite les photos localement dans votre navigateur. Aucune photo n’est envoyée à un serveur. La caméra est utilisée uniquement après votre demande et s’arrête lorsque vous quittez l’écran de capture. Les résultats enregistrés restent dans le stockage local du navigateur. Le QR code contient uniquement l’adresse de la page, sans photo ni mesure.',guideTitle:'Guide de mesure',guideText:'Cet outil fournit une estimation. Pour les photos, placez une référence de longueur connue sur le même plan que la bague, puis photographiez verticalement. Sélectionnez précisément les bords intérieurs et la référence. Pour le doigt, utilisez une bande de papier ajustée ou un mètre souple. Le confort varie selon la forme du doigt, la température et la largeur de la bague. Confirmez avec un kit physique avant tout achat.',cameraError:'Caméra indisponible ou autorisation refusée. Vous pouvez choisir une photo.',capture:'Prendre la photo',cancel:'Annuler',cameraTitle:'Photographiez votre bague',cameraSub:'La bague et la référence doivent être à plat, visibles et nettes.',loading:'Ouverture de la caméra…',imageError:'Impossible de lire ce fichier. Choisissez une photo JPG, PNG ou WebP.',localQr:'Pour scanner ce code sur un téléphone, ouvrez le site publié. Localhost est accessible uniquement sur cet ordinateur.',close:'Fermer',chartTitle:'Tableau des tailles standard',chartSub:'Tailles US et dimensions intérieures approximatives.'}
};
const t=k=>translations[lang][k];
const ringArt='<svg viewBox="0 0 180 150" fill="none" aria-hidden="true"><rect x="9" y="47" width="111" height="70" rx="8" fill="#fff" stroke="#d4dbe0" stroke-width="2"/><path d="M23 68h40m-40 10h23" stroke="#d4dbe0" stroke-width="3" stroke-linecap="round"/><ellipse cx="124" cy="78" rx="30" ry="36" stroke="#e8ced8" stroke-width="13"/><ellipse cx="124" cy="78" rx="30" ry="36" stroke="#d995ad" stroke-width="1.5"/><path d="m124 23 0-9m40 22 7-7m-73-2-6-7" stroke="#d3a5b6" stroke-width="2" stroke-linecap="round"/></svg>';
const paperArt='<svg viewBox="0 0 180 150" fill="none" aria-hidden="true"><rect x="10" y="80" width="160" height="28" rx="3" fill="white" stroke="#cbd4db" stroke-width="2"/><path d="M24 80v15m14-15v8m14-8v15m14-15v8m14-8v15m14-15v8m14-8v15m14-15v8m14-8v15m14-15v8" stroke="#a4aeb7" stroke-width="2"/><path d="M45 60c0-22 62-22 62 0v21c0 22-62 22-62 0Z" fill="#f4e1e8" stroke="#cf9bad" stroke-width="2"/><ellipse cx="76" cy="60" rx="31" ry="16" fill="white" stroke="#cf9bad" stroke-width="2"/><path d="M107 70h26" stroke="#cf9bad" stroke-width="2"/></svg>';
function stopCamera(){if(stream){stream.getTracks().forEach(track=>track.stop());stream=null;}}
function go(next,back=false){stopCamera();if(!back)history.push(screen);screen=next;render();window.scrollTo(0,0);}
function back(){go(history.pop()||'welcome',true);}
function legal(){return `<p class="legal">${t('legal')} <button class="link" data-policy="privacy">${t('privacy')}</button> ${t('and')} <button class="link" data-policy="terms">${t('terms')}</button>.</p>`;}
function shell(step,content){return `<section class="wizard"><nav class="topbar"><button class="back" id="back" aria-label="${t('back')}">‹</button><span class="eyebrow" style="margin:0">${step?`${t('step')} ${step} / 4`:''}</span><button class="language" id="language">${lang==='en'?'FR':'EN'}</button></nav>${step?`<div class="progress"><span style="width:${step*25}%"></span></div>`:''}${content}</section>`;}
function heading(title,sub){return `<h1 tabindex="-1">${t(title)}</h1><p>${t(sub)}</p>`;}
function primary(id,key){return `<button class="primary" id="${id}">${t(key)}</button>`;}
function error(message){let node=document.querySelector('#error');if(node){node.textContent=message;node.setAttribute('role','alert');}}
function photoCanvas(){return `<div class="photo-area"><canvas id="measurement" tabindex="0" aria-label="${t(phase==='reference'?'refSub':'diamSub')}" role="img"></canvas></div><div class="photo-tools"><span id="point-count">0 / 2 ${t('points')}</span><button id="reset">${t('reset')}</button></div><p class="photo-detail">${lang==='en'?'Tap once to place a point. Tap again to place the other end.':'Touchez une fois pour chaque extrémité.'}</p>`;}
function render(){
document.documentElement.lang=lang;document.title=t('welcome');
if(screen==='qr'){
app.innerHTML=`<h1>${t('title')}</h1><section class="qr-panel"><h2>${t('subtitle')}</h2><p>${t('scan')}</p><div class="qr" id="qr" aria-label="QR code to continue on a phone"></div></section>${legal()}<div class="device-action"><button class="subtle" id="continue">${t('device')}</button><button class="language" id="language">${lang==='en'?'FR':'EN'}</button></div>`;
const url=new URL(location.href);url.search='';url.searchParams.set('mobile','1');url.searchParams.set('lang',lang);const qr=qrcode(0,'M');qr.addData(url.href);qr.make();document.querySelector('#qr').innerHTML=qr.createSvgTag({cellSize:4,margin:0,scalable:true});
document.querySelector('#continue').onclick=()=>{const next=new URL(location.href);next.searchParams.set('mobile','1');next.searchParams.set('lang',lang);location.href=next.href;};
if(['localhost','127.0.0.1'].includes(location.hostname)){const note=document.createElement('p');note.className='mini';note.textContent=t('localQr');app.append(note);}
} else if(screen==='welcome'){
app.innerHTML=shell(0,heading('welcome','intro')+`<div class="illustration">${ringArt}</div><div class="feature"><span>✓</span>${t('minutes')}</div><div class="feature"><span>✓</span>${t('private')}</div><div class="feature"><span>✓</span>${t('need')}</div><div style="height:14px"></div>`+primary('start','start')+legal());
document.querySelector('#start').onclick=()=>go('method');
} else if(screen==='method'){
app.innerHTML=shell(1,heading('choose','chooseSub')+`<div class="choices"><button class="choice" id="ring"><span class="icon circle-symbol">◯</span><span><strong>${t('ring')}</strong><small>${t('ringSub')}</small></span><span style="margin-left:auto">›</span></button><button class="choice" id="finger"><span class="icon">⌁</span><span><strong>${t('finger')}</strong><small>${t('fingerSub')}</small></span><span style="margin-left:auto">›</span></button></div><p class="notice">${t('private')}</p>`);
document.querySelector('#ring').onclick=()=>go('prepare');document.querySelector('#finger').onclick=()=>go('wrap');
} else if(screen==='prepare'){
app.innerHTML=shell(2,heading('prepare','prepareSub')+`<div class="illustration">${ringArt}</div><ol class="steps">${['photo1','photo2','photo3','photo4'].map(k=>`<li>${t(k)}</li>`).join('')}</ol><input class="file-input" id="photo" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif">`+primary('upload','upload')+`<button class="secondary" id="camera">${t('camera')}</button><p id="error" class="error"></p><p class="notice">${t('photoNote')}</p>`);
document.querySelector('#upload').onclick=()=>document.querySelector('#photo').click();document.querySelector('#photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>30*1024*1024){error(lang==='en'?'Please choose a photo smaller than 30 MB.':'Choisissez une photo de moins de 30 Mo.');return;}try{const bitmap=await createImageBitmap(file);photo=document.createElement('canvas');const ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));photo.width=Math.round(bitmap.width*ratio);photo.height=Math.round(bitmap.height*ratio);photo.getContext('2d').drawImage(bitmap,0,0,photo.width,photo.height);bitmap.close();phase='reference';points=[];go('reference');}catch{error(t('imageError'));}};
document.querySelector('#camera').onclick=()=>go('camera');
} else if(screen==='camera'){
app.innerHTML=shell(2,heading('cameraTitle','cameraSub')+`<div class="photo-area"><video id="video" autoplay muted playsinline style="width:100%;display:block"></video></div><p id="status" class="mini">${t('loading')}</p><p id="error" class="error"></p><button class="primary" id="capture" disabled>${t('capture')}</button><button class="secondary" id="cancel">${t('cancel')}</button>`);
document.querySelector('#cancel').onclick=back;
document.querySelector('#capture').onclick=()=>{const video=document.querySelector('#video');if(!video.videoWidth)return;photo=document.createElement('canvas');const ratio=Math.min(1,1600/Math.max(video.videoWidth,video.videoHeight));photo.width=video.videoWidth*ratio;photo.height=video.videoHeight*ratio;photo.getContext('2d').drawImage(video,0,0,photo.width,photo.height);phase='reference';points=[];go('reference');};
openCamera();
} else if(screen==='wrap'){
app.innerHTML=shell(2,heading('wrap','wrapSub')+`<div class="illustration">${paperArt}</div><ol class="steps">${['wrap1','wrap2','wrap3','wrap4'].map(k=>`<li>${t(k)}</li>`).join('')}</ol>`+primary('input','input'));
document.querySelector('#input').onclick=()=>go('circumference');
} else if(screen==='circumference'){
app.innerHTML=shell(3,heading('circLabel','circSub')+`<div class="illustration">${paperArt}</div><form id="circ-form"><label class="input-label" for="circ">${t('circLabel')}</label><div class="number-input"><input id="circ" name="circ" inputmode="decimal" type="text" autocomplete="off" placeholder="54.0" aria-describedby="error"><span>mm</span></div><p class="error" id="error"></p><button class="primary" type="submit">${t('size')}</button></form>`);
document.querySelector('#circ-form').onsubmit=e=>{e.preventDefault();try{result=fromCircumference(Number(document.querySelector('#circ').value.trim().replace(',','.')));result.method='paperMethod';go('result');}catch{error(t('range'));}};
} else if(screen==='reference'){
points=[];phase='reference';
app.innerHTML=shell(3,heading('ref','refSub')+`<label class="input-label" for="reference-object">${t('object')}</label><select id="reference-object"><option value="85.6">${t('card')}</option><option value="53.98">${t('shortCard')}</option><option value="custom">${t('ruler')}</option></select><div id="custom-field" hidden><label class="input-label" for="custom-length">${t('custom')}</label><div class="number-input"><input id="custom-length" type="number" min="1" max="300" value="50" inputmode="decimal"><span>mm</span></div></div>`+photoCanvas()+`<div class="photo-guidance">${t('refHelp')}</div><p class="error" id="error"></p><button class="primary" id="next" disabled>${t('next')}</button><button class="subtle" id="retake" style="display:block;margin:auto">${t('retake')}</button>`);
referenceMm=85.6;document.querySelector('#reference-object').onchange=e=>{document.querySelector('#custom-field').hidden=e.target.value!=='custom';referenceMm=e.target.value==='custom'?Number(document.querySelector('#custom-length').value):Number(e.target.value);};document.querySelector('#custom-length').oninput=e=>{referenceMm=Number(e.target.value);};
bindCanvas();document.querySelector('#next').onclick=()=>{if(points.length!==2||distance(points)<5||!Number.isFinite(referenceMm)||referenceMm<1||referenceMm>300){error(lang==='en'?'Select a clear reference and enter a length from 1 to 300 mm.':'Sélectionnez une référence et une longueur de 1 à 300 mm.');return;}photo.referencePixels=distance(points);photo.referenceMm=referenceMm;go('diameter');};document.querySelector('#retake').onclick=()=>go('prepare');
} else if(screen==='diameter'){
phase='diameter';points=[];app.innerHTML=shell(3,heading('diam','diamSub')+photoCanvas()+`<div class="photo-guidance">${t('diamHelp')}</div><p id="error" class="error"></p><button class="primary" id="next" disabled>${t('size')}</button>`);
bindCanvas();document.querySelector('#next').onclick=()=>{try{result=fromPhoto(photo.referencePixels,distance(points),photo.referenceMm);result.method='photoMethod';go('result');}catch{error(t('out'));}};
} else if(screen==='result'){
app.innerHTML=shell(4,`<div class="result"><div class="success-mark">✓</div>`+heading('done','doneSub')+`<div class="result-circle"><small>${t('us')}</small><strong>${result.us}</strong></div><div class="metrics"><div><small>${t('eu')}</small><strong>${result.eu}</strong></div><div><small>${t('diameter')}</small><strong>${result.diameter.toFixed(2)} mm</strong></div></div><p class="mini">${t('circ')}: ${result.circumference.toFixed(1)} mm · ${t(result.method)}</p>`+primary('save','save')+`<button class="secondary" id="repeat">${t('repeat')}</button><p class="notice">${t('resultNote')}</p><button class="subtle" id="chart">${t('chart')}</button><p id="saved" class="saved" role="status"></p></div>`);
document.querySelector('#save').onclick=()=>{try{localStorage.setItem('ring-sizing-result',JSON.stringify({...result,date:new Date().toISOString()}));document.querySelector('#saved').textContent=t('saved');}catch{document.querySelector('#saved').textContent=lang==='en'?'Browser storage is unavailable. Download your result below.':'Stockage indisponible. Téléchargez le résultat ci-dessous.';}const text=`Ring size estimate\nUS: ${result.us}\nEU: ${result.eu}\nInner diameter: ${result.diameter.toFixed(2)} mm\nCircumference: ${result.circumference.toFixed(1)} mm\nMethod: ${t(result.method)}\n${t('resultNote')}`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='my-ring-size.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};document.querySelector('#repeat').onclick=()=>{photo=null;result=null;history=['welcome'];go('method',true);};document.querySelector('#chart').onclick=showChart;
}
document.querySelector('#back')?.addEventListener('click',back);document.querySelector('#language')?.addEventListener('click',()=>{lang=lang==='en'?'fr':'en';render();});document.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>showPolicy(b.dataset.policy));
if(screen!=='qr')document.querySelector('h1')?.focus({preventScroll:true});
}
async function openCamera(){try{const current=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1600}},audio:false});if(screen!=='camera'){current.getTracks().forEach(t=>t.stop());return;}stream=current;const video=document.querySelector('#video');video.srcObject=stream;video.onloadedmetadata=()=>{document.querySelector('#capture').disabled=false;document.querySelector('#status').textContent='';};}catch{if(screen==='camera'){error(t('cameraError'));document.querySelector('#status').textContent='';}}}
function distance(p){return p.length===2?Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y):0;}
function bindCanvas(){const canvas=document.querySelector('#measurement');canvas.width=photo.width;canvas.height=photo.height;draw();canvas.onclick=e=>{const r=canvas.getBoundingClientRect();if(points.length===2)points=[];points.push({x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height});draw();document.querySelector('#point-count').textContent=`${points.length} / 2 ${t('points')}`;document.querySelector('#next').disabled=points.length!==2||distance(points)<5;};document.querySelector('#reset').onclick=()=>{points=[];draw();document.querySelector('#point-count').textContent=`0 / 2 ${t('points')}`;document.querySelector('#next').disabled=true;error('');};}
function draw(){const canvas=document.querySelector('#measurement');if(!canvas||!photo)return;const ctx=canvas.getContext('2d');ctx.drawImage(photo,0,0);const scale=canvas.width/canvas.getBoundingClientRect().width;ctx.lineWidth=2*scale;ctx.strokeStyle=phase==='reference'?'#dd7b9f':'#4bb5b9';if(points.length===2){ctx.beginPath();ctx.moveTo(points[0].x,points[0].y);ctx.lineTo(points[1].x,points[1].y);ctx.stroke();}points.forEach((p,i)=>{ctx.beginPath();ctx.arc(p.x,p.y,7*scale,0,Math.PI*2);ctx.fillStyle='white';ctx.fill();ctx.stroke();ctx.font=`bold ${10*scale}px Arial`;ctx.fillStyle='#1d2931';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(i+1),p.x,p.y);});}
const policy=document.querySelector('#policy');document.querySelectorAll('#policy .close,#policy .dismiss').forEach(b=>b.onclick=()=>policy.close());policy.addEventListener('click',e=>{if(e.target===policy){const r=policy.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)policy.close();}});
function showPolicy(kind){policy.querySelector('h2').textContent=t(kind==='privacy'?'policyTitle':'guideTitle');policy.querySelector('div').innerHTML=`<p>${t(kind==='privacy'?'policyText':'guideText')}</p>`;policy.querySelector('.dismiss').textContent=t('close');policy.showModal();}
function showChart(){policy.querySelector('h2').textContent=t('chartTitle');policy.querySelector('div').innerHTML=`<p>${t('chartSub')}</p><table style="width:100%;font-size:13px;border-collapse:collapse"><thead><tr><th scope="col">US</th><th scope="col">EU</th><th scope="col">${t('diameter')}</th></tr></thead><tbody>${Array.from({length:13},(_,i)=>{const us=i+3,d=11.63+.8128*us;return `<tr><td style="padding:9px;border-bottom:1px solid #eee;text-align:center">${us}</td><td style="padding:9px;border-bottom:1px solid #eee;text-align:center">${Math.round(d*Math.PI)}</td><td style="padding:9px;border-bottom:1px solid #eee;text-align:center">${d.toFixed(2)} mm</td></tr>`;}).join('')}</tbody></table>`;policy.querySelector('.dismiss').textContent=t('close');policy.showModal();}
window.addEventListener('pagehide',stopCamera);document.addEventListener('visibilitychange',()=>{if(screen==='camera'){if(document.hidden){stopCamera();if(document.querySelector('#capture'))document.querySelector('#capture').disabled=true;}else if(!stream){openCamera();}}});
screen=mobile?'welcome':'qr';render();
